window.airGlass2Shaders={"liquid":"#version 300 es\nprecision highp float;\nprecision highp int;\n// Liquid Glass for the macdock Dock.\n//\n// Build:  qsb --qt6 -o liquidglass.frag.qsb liquidglass.frag\n// (shell.qml runs this automatically on first use and caches the result in ~/.config/macdock/)\n//\n// The shader treats the Dock as a slab of curved glass sitting on top of a live backdrop texture:\n//   * a rounded-rect signed distance field gives the distance to the edge and the edge direction\n//   * a convex \"squircle\" bezel profile turns that into a surface normal\n//   * Snell's law (refract) turns the normal into a lateral shift of the sampled backdrop\n//   * the backdrop is sampled per colour channel (dispersion) through a small disk blur\n//   * saturation / tint / milky lift, then specular rim, inner depth shading and a soft drop shadow\n\nin vec2 qt_TexCoord0;\nout vec4 fragColor;\n\nuniform mat4 qt_Matrix;\nuniform float qt_Opacity;\nuniform vec2 itemSize;\nuniform vec2 glassSize;\nuniform vec2 srcSize;\nuniform vec2 srcOffset;\nuniform float pad;\nuniform float radius;\nuniform float bezel;\nuniform float thickness;\nuniform float dispersion;\nuniform float blurPx;\nuniform float tintMix;\nuniform float saturation;\nuniform float dark;\nuniform float debug;\nuniform float rim;\nuniform float grain;\nuniform float magnify;\nuniform float shadowAmt;\nuniform float rimTint;\nuniform float ringW;\nuniform float flatInner;\n\nuniform sampler2D src;\n\n\nuniform float airEdgeMode;\nuniform float airEdgeInset;\nuniform vec4 airCorners;\nuniform vec2 airSourceScale;\nfloat airBox(vec2 p,vec2 hs,float r){vec2 q=abs(p)-hs+r;return length(max(q,0.0))+min(max(q.x,q.y),0.0)-r;}\nfloat airDistance(vec2 p){\n vec2 q=p-vec2(airEdgeInset,0.0)-glassSize*.5;\n float r=q.y<0.0?(q.x<0.0?airCorners.x:airCorners.y):(q.x<0.0?airCorners.w:airCorners.z);\n float d=airBox(q,glassSize*.5,min(r,min(glassSize.x,glassSize.y)*.5));\n if(airEdgeMode<.5)return d;\n float cy=airEdgeMode<1.5?glassSize.y-12.0:12.0;\n float by=airEdgeMode<1.5?glassSize.y-6.0:6.0;\n float l=max(airBox(p-vec2(6.0,by),vec2(6.0),0.0),12.25-length(p-vec2(0.0,cy)));\n float rr=max(airBox(p-vec2(glassSize.x+18.0,by),vec2(6.0),0.0),12.25-length(p-vec2(glassSize.x+24.0,cy)));\n return min(d,min(l,rr));\n}\nvec2 airNormal(vec2 p){vec2 g=vec2(airDistance(p+vec2(.5,0.0))-airDistance(p-vec2(.5,0.0)),airDistance(p+vec2(0.0,.5))-airDistance(p-vec2(0.0,.5)));return length(g)>.0001?normalize(g):vec2(0.0,-1.0);}\n\nconst int   TAPS   = 24;\nconst float GOLDEN = 2.39996323;\n\n// Natural blur, no \"duplicated background\" ghosts:\n//  * every tap reads a pre-blurred mip level sized to the gap between taps, so the taps overlap into one\n//    smooth surface instead of showing as separate copies of the content\n//  * Gaussian weights give a soft falloff instead of a hard disk edge\n//  * the tap pattern is rotated per pixel (interleaved gradient noise), so any leftover gaps turn into\n//    fine grain instead of repeating ghost lines\n//  * one shared pattern for all three colour channels (dispersion only shifts the centre)\n// Needs `mipmap: true` on the ShaderEffectSource (set in MacBar.qml / MacDock.qml).\nvec3 backdropLod(vec2 pItem, float lod)\n{\n    vec2 uv = (pItem * airSourceScale + srcOffset) / srcSize;\n    return textureLod(src, clamp(uv, vec2(0.001), vec2(0.999)), lod).rgb;\n}\n\nfloat ign(vec2 p)\n{\n    return fract(52.9829189 * fract(dot(p, vec2(0.06711056, 0.00583715))));\n}\n\nvec3 blurredDisp(vec2 pItem, vec2 disp, float disperse, float rad)\n{\n    float R   = max(rad, 0.5) * 1.5;                       // Gaussian reaches further than a flat disk\n    float gap = R * sqrt(3.14159265 / float(TAPS));        // spacing between neighbouring taps, px\n    float lod = clamp(log2(max(gap, 1.0)) + 0.35, 0.0, 6.0);\n    float rot = ign(gl_FragCoord.xy) * 6.2831853;\n    vec3  acc = vec3(0.0);\n    float wsum = 0.0;\n    for (int i = 0; i < TAPS; ++i) {\n        float fi = float(i) + 0.5;\n        float r  = sqrt(fi / float(TAPS));\n        float a  = fi * GOLDEN + rot;\n        float w  = exp(-2.2 * r * r);\n        vec2  o  = vec2(cos(a), sin(a)) * r * R;\n        vec3  c;\n        c.r = backdropLod(pItem + o + disp * (1.0 + disperse), lod).r;\n        c.g = backdropLod(pItem + o + disp,                    lod).g;\n        c.b = backdropLod(pItem + o + disp * (1.0 - disperse), lod).b;\n        acc  += c * w;\n        wsum += w;\n    }\n    return acc / wsum;\n}\n\nfloat hash12(vec2 p)\n{\n    vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n    p3 += dot(p3, p3.yzx + 33.33);\n    return fract((p3.x + p3.y) * p3.z);\n}\n\nfloat roundBox(vec2 q, vec2 hs, float r)\n{\n    vec2 d = abs(q) - (hs - r);\n    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0) - r;\n}\n\nvoid main()\n{\n    vec2 p  = qt_TexCoord0 * itemSize;\n    vec2 hs = glassSize * 0.5;\n    vec2 q  = p - vec2(pad) - hs - vec2(airEdgeInset,0.0);\n    float r = min(radius, min(hs.x, hs.y));\n\n    float sd  = airDistance(p);               // < 0 inside the glass\n    float cov = clamp(0.5 - sd, 0.0, 1.0);        // anti-aliased coverage\n\n    if (debug > 0.5) {\n        vec4 s = texture(src, clamp((p + srcOffset) / srcSize, vec2(0.001), vec2(0.999)));\n        fragColor = (s.a < 0.01 ? vec4(1.0, 0.0, 1.0, 1.0) : vec4(s.rgb / max(s.a, 1e-3), 1.0)) * cov * qt_Opacity;\n        return;\n    }\n\n    // ── soft drop shadow (only visible outside the glass) ──\n    float sds    = airDistance(p - vec2(0.0,3.0));\n    float shadow = 0.30 * shadowAmt * (1.0 - smoothstep(-2.0, 9.0, sds));\n    if (sd > 1.0) {\n        fragColor = vec4(0.0, 0.0, 0.0, shadow) * qt_Opacity;\n        return;\n    }\n\n    // ── distance to edge + outward edge direction ──\n    float t = max(-sd, 0.0);\n    vec2 d2 = abs(q) - (hs - r);\n    vec2 sg = vec2(q.x >= 0.0 ? 1.0 : -1.0, q.y >= 0.0 ? 1.0 : -1.0);\n    vec2 m  = max(d2, 0.0);\n    vec2 g = airNormal(p);\n\n    // ── convex squircle bezel → surface normal ──\n    float bz   = max(bezel, 1.0) * 1.45;           // wider bezel: the glass reads thicker\n    float u    = clamp(t / bz, 0.0, 1.0);\n    float om   = 1.0 - u;\n    float om4  = om * om * om * om;\n    float slope = (om * om * om) / pow(max(1.0 - om4, 1e-3), 0.75);\n    slope = min(slope, 7.0);\n    vec3 n = normalize(vec3(g * slope, 1.0));\n\n    // ── refraction: glass n≈1.5, ray enters straight down ──\n    vec3 rd   = refract(vec3(0.0, 0.0, -1.0), n, 1.0 / 1.5);\n    vec2 disp = rd.xy / max(-rd.z, 0.2) * thickness * 1.35;\n\n    // the whole slab acts as a gentle vertical lens; blur is crisper right at the curved rim\n    vec2 ps = vec2(p.x, (p.y - pad - hs.y) * (1.0 - magnify * 1.5) + pad + hs.y);\n    float rad = blurPx * mix(0.45, 1.0, smoothstep(0.0, bz, t));\n\n    vec3 col = blurredDisp(ps, disp, dispersion * 0.6, rad);\n\n    // ── colour grading: vibrancy, tint, milky lift ──\n    float l = dot(col, vec3(0.2126, 0.7152, 0.0722));\n    col = mix(vec3(l), col, saturation);\n    vec3 tintC = mix(vec3(1.0), vec3(0.09, 0.09, 0.10), dark);\n    col = mix(col, tintC, tintMix);\n    col += mix(0.055, 0.020, dark);\n\n    // ── depth: soft top sheen, darker lower inner edge ──\n    float ty = clamp((q.y + hs.y) / glassSize.y, 0.0, 1.0);\n    col += (1.0 - ty) * mix(0.040, 0.030, dark);\n    float innerK = 1.0 - clamp(flatInner, 0.0, 1.0);\n    col *= 1.0 - 0.12 * exp(-t / 6.0) * clamp(g.y, 0.0, 1.0) * innerK;\n    col *= 1.0 - 0.10 * exp(-t / (bz * 0.45)) * innerK;          // thick glass absorbs light toward the edge (heavier feel)\n\n    // colour of the rim / border: white, or (rimTint) a brighter shade of what the glass looks like at this spot\n    vec3 rimCol = mix(vec3(0.96, 0.98, 1.0), clamp(col * 1.5 + 0.12, 0.0, 1.0), rimTint);\n\n    // ── specular rim, light from the top-left ──\n    vec2  L      = normalize(vec2(-0.55, -0.83));\n    float facing = dot(g, L);\n    float spec   = pow(max(facing, 0.0), 1.6) + 0.55 * pow(max(-facing, 0.0), 2.2);\n    float hair   = exp(-t / 1.1);\n    float wide   = exp(-t / 5.0);\n    float edgeHi = hair * (0.18 + 0.78 * spec) + wide * 0.10 * (0.30 + spec);\n    edgeHi *= rim * mix(0.85, 1.0, dark);\n    col += edgeHi * rimCol;\n\n    // meniscus: a soft second highlight inside the rim, like surface tension pulling the liquid together\n    float mx  = (t - bz * 0.5) / (bz * 0.2 + 1.0);\n    float men = exp(-mx * mx);\n    col += men * 0.07 * (0.35 + spec) * rim * rimCol;\n\n    // thin border line right at the edge (anti-aliased), brighter on the lit side\n    if (ringW > 0.0) {\n        float ring = 1.0 - smoothstep(ringW * 0.5, ringW * 0.5 + 1.0, t);\n        col = mix(col, rimCol, ring * (0.55 + 0.35 * clamp(facing * 0.5 + 0.5, 0.0, 1.0)));\n    }\n\n    // ringW < 0: \"corner light\" border. A line (|ringW| px) that runs all the way round the glass and fades out only at the\n    // top-right and bottom-left corners, and takes a bright shade of the backdrop colour at that spot (dynamic: it follows what\n    // is behind the glass). Used by the Control Center; everything else keeps ringW >= 0 and is unchanged.\n    if (ringW < 0.0) {\n        float rw   = -ringW;\n        float ring = 1.0 - smoothstep(rw * 0.5, rw * 0.5 + 1.0, t);\n        float glow = exp(-t / (rw * 2.2)) * 0.30;\n        float fall = max(r * 3.0, 26.0);\n        float wTR  = pow(clamp(1.0 - length(q - vec2( hs.x, -hs.y)) / fall, 0.0, 1.0), 1.2);\n        float wBL  = pow(clamp(1.0 - length(q - vec2(-hs.x,  hs.y)) / fall, 0.0, 1.0), 1.2);\n        float cw   = 1.0 - max(wTR, wBL);\n        vec3  ringCol = clamp(col * 2.0 + 0.18, 0.0, 1.0);\n        col = mix(col, ringCol, clamp((ring + glow) * cw, 0.0, 1.0) * 0.95);\n    }\n\n    // fine triangular-distribution grain, same on every channel so it reads as texture, not colour noise\n    float gn = hash12(gl_FragCoord.xy) + hash12(gl_FragCoord.xy * 1.7 + 17.0) - 1.0;\n    col += gn * grain;\n\n    col = clamp(col, 0.0, 1.0);\n\n    float a = cov + shadow * (1.0 - cov);\n    fragColor = vec4(col * cov, a) * qt_Opacity;   // premultiplied alpha\n}\n","dock":"#version 300 es\nprecision highp float;\nprecision highp int;\n// Liquid Glass for the Dock, tuned toward macOS Tahoe.\n//\n// Build:  qsb --qt6 -o dockglass.frag.qsb dockglass.frag\n// (MacDock.qml runs this automatically and caches the result in ~/.config/macdock/. If the build fails the Dock keeps\n//  using the shared liquidglass.frag, so nothing else in the shell depends on this file.)\n//\n// This is liquidglass.frag's refraction model (rounded-rect SDF -> convex bezel -> Snell's law -> dispersion) with the\n// parts that make the Dock read as Tahoe glass reworked:\n//   * edge: a crisp ~1 px specular line that is strong where the edge faces the light (top-left) and weaker on the far side,\n//           a soft pooled glow just inside it, and a ~1 px dark line hugging the OUTSIDE of the edge so the glass stays\n//           separated from bright wallpapers. Replaces the QML Canvas border, which repainted every frame while icons magnified.\n//   * tint: adaptive - bright backdrops get more dark tint (so white icons / labels stay legible), dark backdrops get less,\n//           instead of one flat tint amount.\n//   * depth: the heavy dark inner edge is gone (Tahoe glass is clear, not smoked); only a faint absorption toward the edge stays.\n//   * shadow: a wide ambient layer plus a tight contact layer, offset down, instead of one short 9 px falloff.\n//\n// Item padding (`pad`) must be >= 30 px so the ambient shadow is not clipped.\n\nin vec2 qt_TexCoord0;\nout vec4 fragColor;\n\nuniform mat4 qt_Matrix;\nuniform float qt_Opacity;\nuniform vec2 itemSize;\nuniform vec2 glassSize;\nuniform vec2 srcSize;\nuniform vec2 srcOffset;\nuniform float pad;\nuniform float radius;\nuniform float bezel;\nuniform float thickness;\nuniform float dispersion;\nuniform float blurPx;\nuniform float tintMix;\nuniform float saturation;\nuniform float dark;\nuniform float debug;\nuniform float rim;\nuniform float grain;\nuniform float magnify;\nuniform float shadowAmt;\nuniform vec4 edgeTint;\n\nuniform sampler2D src;\n\n\nuniform float airEdgeMode;\nuniform float airEdgeInset;\nuniform vec4 airCorners;\nuniform vec2 airSourceScale;\nfloat airBox(vec2 p,vec2 hs,float r){vec2 q=abs(p)-hs+r;return length(max(q,0.0))+min(max(q.x,q.y),0.0)-r;}\nfloat airDistance(vec2 p){\n vec2 q=p-vec2(airEdgeInset,0.0)-glassSize*.5;\n float r=q.y<0.0?(q.x<0.0?airCorners.x:airCorners.y):(q.x<0.0?airCorners.w:airCorners.z);\n float d=airBox(q,glassSize*.5,min(r,min(glassSize.x,glassSize.y)*.5));\n if(airEdgeMode<.5)return d;\n float cy=airEdgeMode<1.5?glassSize.y-12.0:12.0;\n float by=airEdgeMode<1.5?glassSize.y-6.0:6.0;\n float l=max(airBox(p-vec2(6.0,by),vec2(6.0),0.0),12.25-length(p-vec2(0.0,cy)));\n float rr=max(airBox(p-vec2(glassSize.x+18.0,by),vec2(6.0),0.0),12.25-length(p-vec2(glassSize.x+24.0,cy)));\n return min(d,min(l,rr));\n}\nvec2 airNormal(vec2 p){vec2 g=vec2(airDistance(p+vec2(.5,0.0))-airDistance(p-vec2(.5,0.0)),airDistance(p+vec2(0.0,.5))-airDistance(p-vec2(0.0,.5)));return length(g)>.0001?normalize(g):vec2(0.0,-1.0);}\n\nconst int   TAPS   = 24;\nconst float GOLDEN = 2.39996323;\n\n// Same natural blur as liquidglass.frag: every tap reads a pre-blurred mip level sized to the gap between taps, Gaussian\n// weights, and a per-pixel rotated pattern so leftover gaps turn into grain rather than ghost copies.\n// Needs `mipmap: true` on the ShaderEffectSource.\nvec3 backdropLod(vec2 pItem, float lod)\n{\n    vec2 uv = (pItem * airSourceScale + srcOffset) / srcSize;\n    return textureLod(src, clamp(uv, vec2(0.001), vec2(0.999)), lod).rgb;\n}\n\nfloat ign(vec2 p)\n{\n    return fract(52.9829189 * fract(dot(p, vec2(0.06711056, 0.00583715))));\n}\n\nvec3 blurredDisp(vec2 pItem, vec2 disp, float disperse, float rad)\n{\n    float R   = max(rad, 0.5) * 1.5;\n    float gap = R * sqrt(3.14159265 / float(TAPS));\n    float lod = clamp(log2(max(gap, 1.0)) + 0.35, 0.0, 6.0);\n    float rot = ign(gl_FragCoord.xy) * 6.2831853;\n    vec3  acc = vec3(0.0);\n    float wsum = 0.0;\n    for (int i = 0; i < TAPS; ++i) {\n        float fi = float(i) + 0.5;\n        float r  = sqrt(fi / float(TAPS));\n        float a  = fi * GOLDEN + rot;\n        float w  = exp(-2.2 * r * r);\n        vec2  o  = vec2(cos(a), sin(a)) * r * R;\n        vec3  c;\n        c.r = backdropLod(pItem + o + disp * (1.0 + disperse), lod).r;\n        c.g = backdropLod(pItem + o + disp,                    lod).g;\n        c.b = backdropLod(pItem + o + disp * (1.0 - disperse), lod).b;\n        acc  += c * w;\n        wsum += w;\n    }\n    return acc / wsum;\n}\n\nfloat hash12(vec2 p)\n{\n    vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n    p3 += dot(p3, p3.yzx + 33.33);\n    return fract((p3.x + p3.y) * p3.z);\n}\n\nfloat roundBox(vec2 q, vec2 hs, float r)\n{\n    vec2 d = abs(q) - (hs - r);\n    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0) - r;\n}\n\nvoid main()\n{\n    vec2 p  = qt_TexCoord0 * itemSize;\n    vec2 hs = glassSize * 0.5;\n    vec2 q  = p - vec2(pad) - hs - vec2(airEdgeInset,0.0);\n    float r = min(radius, min(hs.x, hs.y));\n\n    float sd  = airDistance(p);               // < 0 inside the glass\n    float cov = clamp(0.5 - sd, 0.0, 1.0);        // anti-aliased coverage\n\n    if (debug > 0.5) {\n        vec4 s = texture(src, clamp((p + srcOffset) / srcSize, vec2(0.001), vec2(0.999)));\n        fragColor = (s.a < 0.01 ? vec4(1.0, 0.0, 1.0, 1.0) : vec4(s.rgb / max(s.a, 1e-3), 1.0)) * cov * qt_Opacity;\n        return;\n    }\n\n    // ── outside the glass: nothing at all (no shadow, no dark outline) ──\n    if (cov <= 0.0) {\n        fragColor = vec4(0.0);\n        return;\n    }\n\n    // ── distance to edge + outward edge direction ──\n    float t = max(-sd, 0.0);\n    vec2 d2 = abs(q) - (hs - r);\n    vec2 sg = vec2(q.x >= 0.0 ? 1.0 : -1.0, q.y >= 0.0 ? 1.0 : -1.0);\n    vec2 m  = max(d2, 0.0);\n    vec2 g = airNormal(p);\n\n    // ── convex squircle bezel -> surface normal ──\n    float bz   = max(bezel, 1.0) * 1.45;\n    float u    = clamp(t / bz, 0.0, 1.0);\n    float om   = 1.0 - u;\n    float om4  = om * om * om * om;\n    float slope = (om * om * om) / pow(max(1.0 - om4, 1e-3), 0.75);\n    slope = min(slope, 7.0);\n    vec3 n = normalize(vec3(g * slope, 1.0));\n\n    // ── refraction: glass n~1.5, ray enters straight down ──\n    vec3 rd   = refract(vec3(0.0, 0.0, -1.0), n, 1.0 / 1.5);\n    vec2 disp = rd.xy / max(-rd.z, 0.2) * thickness * 1.35;\n\n    vec2 ps = vec2(p.x, (p.y - pad - hs.y) * (1.0 - magnify * 1.5) + pad + hs.y);\n    float rad = blurPx * mix(0.45, 1.0, smoothstep(0.0, bz, t));\n\n    vec3 col = blurredDisp(ps, disp, dispersion * 0.6, rad);\n\n    // ── colour: vibrancy, then an ADAPTIVE tint ──\n    float l = dot(col, vec3(0.2126, 0.7152, 0.0722));\n    col = mix(vec3(l), col, saturation);\n    vec3 behind = col;                                            // the colour right behind this pixel, kept for the border below\n    float lw    = smoothstep(0.30, 0.80, l);\n    float adapt = mix(0.78, 1.28, mix(1.0 - lw, lw, dark));       // more tint where the backdrop would fight the icons\n    vec3 tintC  = mix(vec3(1.0), vec3(0.09, 0.09, 0.10), dark);\n    col = mix(col, tintC, clamp(tintMix * adapt, 0.0, 1.0));\n    col += mix(0.055, 0.020, dark);\n\n    // ── depth: soft light from above, faint absorption toward the edge (clear glass, not smoked) ──\n    float ty = clamp((q.y + hs.y) / glassSize.y, 0.0, 1.0);\n    col += (1.0 - ty) * mix(0.040, 0.034, dark);\n\n    // ── edge light, from the top-left ──\n    // identical to the top-bar menus (rimTint = 1): the rim / border take a darker shade of what the glass looks like at this spot\n    vec3 rimCol   = clamp(col * 1.2, 0.0, 1.0);          // 120% of the glass colour (100% = natural) of the glass's own colour (menus use a brighter one: col * 1.5 + 0.12)\n\n    vec2  L      = normalize(vec2(-0.55, -0.83));\n    float facing = dot(g, L);\n    float spec   = pow(max(facing, 0.0), 1.6) + 0.55 * pow(max(-facing, 0.0), 2.2);\n    float crisp  = 1.0 - smoothstep(0.55, 1.55, t);                // the ~1 px line itself\n    float pool   = exp(-t / 3.2);                                  // light pooling just inside it\n    float edgeHi = crisp * (0.26 + 0.74 * spec) * 0.80 + pool * (0.05 + 0.10 * spec);\n    edgeHi *= rim * 1.1 * mix(0.85, 1.0, dark);\n    col += edgeHi * rimCol;\n\n    // thin border line along the very edge, exactly as the menus draw it (ringW = 1 px here)\n    float ringW = 1.0;\n    float ring  = 1.0 - smoothstep(ringW * 0.5, ringW * 0.5 + 1.0, t);\n    col = mix(col, rimCol, ring * (0.55 + 0.35 * clamp(facing * 0.5 + 0.5, 0.0, 1.0)));\n\n    // meniscus: a very faint, wide second highlight inside the rim (kept soft so it never reads as an inner outline)\n    float mx  = (t - bz * 0.5) / (bz * 0.35 + 1.0);\n    float men = exp(-mx * mx);\n    col += men * 0.03 * (0.35 + spec) * rim * rimCol;\n\n    // fine triangular-distribution grain, same on every channel so it reads as texture, not colour noise\n    float gn = hash12(gl_FragCoord.xy) + hash12(gl_FragCoord.xy * 1.7 + 17.0) - 1.0;\n    col += gn * grain;\n\n    col = clamp(col, 0.0, 1.0);\n\n    // premultiplied: the glass over its own outer line / shadow (they only differ from zero in the 1 px anti-aliased band)\n    fragColor = vec4(col * cov, cov) * qt_Opacity;\n}\n","contour":"#version 300 es\nprecision highp float;\nprecision highp int;\n// Contour glow (Spotlight hover): a crisp light line that follows the rounded outline, plus a soft halo,\n// brightest where the cursor is.\n// Build:  /usr/lib/qt6/bin/qsb --qt6 -o contourglow.frag.qsb contourglow.frag\n\nin vec2 qt_TexCoord0;\nout vec4 fragColor;\n\nuniform mat4 qt_Matrix;\nuniform float qt_Opacity;\nuniform vec2 itemSize;\nuniform vec2 mouse;\nuniform float pad;\nuniform float cornerR;\nuniform float amount;\nuniform float spread;\nuniform vec4 tint;\n\nuniform vec2 glassSize;\n\nuniform float airEdgeMode;\nuniform float airEdgeInset;\nuniform vec4 airCorners;\nuniform vec2 airSourceScale;\nfloat airBox(vec2 p,vec2 hs,float r){vec2 q=abs(p)-hs+r;return length(max(q,0.0))+min(max(q.x,q.y),0.0)-r;}\nfloat airDistance(vec2 p){\n vec2 q=p-vec2(airEdgeInset,0.0)-glassSize*.5;\n float r=q.y<0.0?(q.x<0.0?airCorners.x:airCorners.y):(q.x<0.0?airCorners.w:airCorners.z);\n float d=airBox(q,glassSize*.5,min(r,min(glassSize.x,glassSize.y)*.5));\n if(airEdgeMode<.5)return d;\n float cy=airEdgeMode<1.5?glassSize.y-12.0:12.0;\n float by=airEdgeMode<1.5?glassSize.y-6.0:6.0;\n float l=max(airBox(p-vec2(6.0,by),vec2(6.0),0.0),12.25-length(p-vec2(0.0,cy)));\n float rr=max(airBox(p-vec2(glassSize.x+18.0,by),vec2(6.0),0.0),12.25-length(p-vec2(glassSize.x+24.0,cy)));\n return min(d,min(l,rr));\n}\nvec2 airNormal(vec2 p){vec2 g=vec2(airDistance(p+vec2(.5,0.0))-airDistance(p-vec2(.5,0.0)),airDistance(p+vec2(0.0,.5))-airDistance(p-vec2(0.0,.5)));return length(g)>.0001?normalize(g):vec2(0.0,-1.0);}\n\nfloat sdRoundRect(vec2 p, vec2 halfSize, float r)\n{\n    vec2 q = abs(p) - halfSize + r;\n    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;\n}\n\nvoid main()\n{\n    vec2 p = qt_TexCoord0 * itemSize;\n    vec2 c = itemSize * 0.5;\n    float d = airDistance(p);      // 0 on the outline, < 0 inside\n\n    // everything stays INSIDE the shape: a crisp line just inside the outline (anti-aliased over ~0.6 px at the\n    // edge) and a faint inner sheen — no halo spilling outside\n    float inside = 1.0 - smoothstep(-0.3, 0.6, d);\n    float line = exp(-max(-d, 0.0) / 1.0) * inside;\n    float halo = exp(min(d, 0.0) / 5.0) * 0.14 * inside;\n\n    // the part of the outline nearest the cursor lights up most; the rest keeps a faint glow\n    float near = exp(-length(p - (mouse + pad)) / spread);\n    float a = (line * 0.95 + halo) * mix(0.18, 1.0, near) * amount;\n\n    fragColor = vec4(tint.rgb * a, a) * qt_Opacity;\n}\n","preblur":"#version 300 es\nprecision highp float;\nin vec2 qt_TexCoord0;out vec4 fragColor;\nuniform sampler2D src;uniform vec2 axis;uniform float sigma;\nvoid main(){vec4 col=vec4(0.);float total=0.;\n for(int i=-8;i<=8;i++){float x=float(i)*sigma*.375;float weight=exp(-.5*x*x/(sigma*sigma));\n col+=textureLod(src,clamp(qt_TexCoord0+axis*x,vec2(0.),vec2(1.)),0.)*weight;total+=weight;}\n fragColor=col/total;}"};
